// Test_decide runs the slice's specifications: the given events replayed
// through evolve, then decide with the command.
func Test_decide(t *testing.T) {
	tests := []struct {
		name    string
		history []eventsourcing.Event
		cmd     AddItem
		want    []eventsourcing.Event
		wantErr error
		skip    string
	}{
		{
			name: "spec: Add Item - Adding the first item creates the cart",
			cmd:  AddItem{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
			want: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
			},
		},
		{
			name: "spec: Add Item - Adding an item to an existing cart",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
			},
			cmd: AddItem{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			want: []eventsourcing.Event{
				&events.ItemAdded{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			},
		},
		{
			name: "spec: Add Item - A cart holds at most three items",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.ItemAdded{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
			},
			cmd:     AddItem{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			wantErr: errCartIsFull,
		},
		{
			name: "spec: Add Item - A submitted cart takes no more items",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.CartSubmitted{CartID: cartID},
			},
			cmd:     AddItem{CartID: cartID, ItemID: itemID2, ProductID: productID2, Description: "Milk frother", Price: 39.95},
			wantErr: errCartAlreadySubmitted,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.skip != "" {
				t.Skip("TODO: " + tt.skip)
			}
			s := initialState()
			for _, e := range tt.history {
				s = evolve(s, &eventsourcing.Envelope{Event: e})
			}

			got, err := decide(s, tt.cmd)
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("decide() error = %v, want %v", err, tt.wantErr)
			}
			gotJSON, _ := json.Marshal(withoutGenerated(got))
			wantJSON, _ := json.Marshal(tt.want)
			if !bytes.Equal(gotJSON, wantJSON) {
				t.Errorf("decide() = %s, want %s", gotJSON, wantJSON)
			}
		})
	}
}

